(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('advanced-export-expansion', {
    meta: {
      name: 'Advanced Export Expansion',
      type: 'Expansion',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Advanced export capabilities with multiple formats and customization'
    },

    exportPanel: null,

    onAppInit(ctx) {
      ctx.logger.log('Advanced Export Expansion initialized');
      this.createExportPanel(ctx);
      this.addMenuButton(ctx);
    },

    addMenuButton(ctx) {
      // Try to add export button to the UI
      const menuBar = document.querySelector('.menu-bar, .toolbar, nav');
      if (menuBar) {
        const exportBtn = document.createElement('button');
        exportBtn.className = 'btn btn-secondary export-btn';
        exportBtn.innerHTML = '📤 Advanced Export';
        exportBtn.title = 'Open advanced export options';
        exportBtn.addEventListener('click', () => this.showExportPanel());
        menuBar.appendChild(exportBtn);
      }
    },

    createExportPanel(ctx) {
      this.exportPanel = document.createElement('div');
      this.exportPanel.id = 'advanced-export-panel';
      this.exportPanel.className = 'modal';
      this.exportPanel.innerHTML = `
        <div class="modal-content export-modal">
          <div class="modal-header">
            <h2>📤 Advanced Export</h2>
            <button class="modal-close">×</button>
          </div>
          <div class="modal-body">
            <div class="export-section">
              <h3>Format Selection</h3>
              <div class="format-options">
                <label><input type="radio" name="format" value="markdown" checked> Markdown (.md)</label>
                <label><input type="radio" name="format" value="html"> HTML (.html)</label>
                <label><input type="radio" name="format" value="pdf"> PDF (via print)</label>
                <label><input type="radio" name="format" value="txt"> Plain Text (.txt)</label>
                <label><input type="radio" name="format" value="csv"> CSV (.csv)</label>
                <label><input type="radio" name="format" value="json"> JSON (.json)</label>
              </div>
            </div>

            <div class="export-section">
              <h3>Scope</h3>
              <div class="scope-options">
                <label><input type="radio" name="scope" value="current" checked> Current card only</label>
                <label><input type="radio" name="scope" value="tree"> Current card + children</label>
                <label><input type="radio" name="scope" value="tagged"> Cards with specific tag</label>
                <label><input type="radio" name="scope" value="all"> All cards</label>
              </div>
              <div class="tag-select" style="display: none;">
                <label>Tag: <input type="text" class="tag-input" placeholder="Enter tag name"></label>
              </div>
            </div>

            <div class="export-section">
              <h3>Options</h3>
              <div class="export-options">
                <label><input type="checkbox" class="include-metadata" checked> Include metadata (dates, tags)</label>
                <label><input type="checkbox" class="include-hierarchy"> Include hierarchy structure</label>
                <label><input type="checkbox" class="include-toc"> Generate table of contents</label>
                <label><input type="checkbox" class="include-backlinks"> Include backlinks</label>
              </div>
            </div>

            <div class="export-preview">
              <h3>Preview</h3>
              <div class="preview-stats">
                <span>Cards to export: <strong id="export-card-count">1</strong></span>
                <span>Estimated size: <strong id="export-size">~2 KB</strong></span>
              </div>
            </div>
          </div>
          <div class="modal-footer">
            <button class="btn btn-secondary cancel-export">Cancel</button>
            <button class="btn btn-primary do-export">Export</button>
          </div>
        </div>
      `;

      document.body.appendChild(this.exportPanel);
      this.attachExportListeners(ctx);
    },

    attachExportListeners(ctx) {
      const closeBtn = this.exportPanel.querySelector('.modal-close');
      const cancelBtn = this.exportPanel.querySelector('.cancel-export');
      const exportBtn = this.exportPanel.querySelector('.do-export');

      closeBtn.addEventListener('click', () => this.hideExportPanel());
      cancelBtn.addEventListener('click', () => this.hideExportPanel());
      exportBtn.addEventListener('click', () => this.performExport(ctx));

      // Show/hide tag input based on scope
      const scopeRadios = this.exportPanel.querySelectorAll('input[name="scope"]');
      scopeRadios.forEach(radio => {
        radio.addEventListener('change', () => {
          const tagSelect = this.exportPanel.querySelector('.tag-select');
          tagSelect.style.display = radio.value === 'tagged' ? 'block' : 'none';
          this.updatePreview();
        });
      });

      // Update preview on any change
      const allInputs = this.exportPanel.querySelectorAll('input');
      allInputs.forEach(input => {
        input.addEventListener('change', () => this.updatePreview());
      });
    },

    showExportPanel() {
      this.exportPanel.style.display = 'flex';
      this.updatePreview();
    },

    hideExportPanel() {
      this.exportPanel.style.display = 'none';
    },

    updatePreview() {
      const cards = this.getCardsToExport();
      const cardCount = this.exportPanel.querySelector('#export-card-count');
      const sizeEstimate = this.exportPanel.querySelector('#export-size');

      cardCount.textContent = cards.length;

      // Rough size estimate
      const totalSize = cards.reduce((sum, card) => 
        sum + card.title.length + card.body.length, 0
      );
      sizeEstimate.textContent = this.formatBytes(totalSize * 2); // *2 for metadata
    },

    formatBytes(bytes) {
      if (bytes < 1024) return bytes + ' B';
      if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
      return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    },

    getCardsToExport() {
      const scope = this.exportPanel.querySelector('input[name="scope"]:checked').value;
      const allCards = Object.values(window.store?.cards || {});

      switch (scope) {
        case 'current':
          const currentCardId = this.getCurrentCardId();
          return currentCardId ? [allCards.find(c => c.id === currentCardId)].filter(Boolean) : [];

        case 'tree':
          const currentId = this.getCurrentCardId();
          if (!currentId) return [];
          return this.getCardTree(currentId, allCards);

        case 'tagged':
          const tag = this.exportPanel.querySelector('.tag-input').value.trim();
          if (!tag) return [];
          return allCards.filter(card => card.tags && card.tags.includes(tag));

        case 'all':
          return allCards;

        default:
          return [];
      }
    },

    getCurrentCardId() {
      const params = new URLSearchParams(window.location.search);
      return params.get('card') || null;
    },

    getCardTree(cardId, allCards) {
      const card = allCards.find(c => c.id === cardId);
      if (!card) return [];

      const tree = [card];
      if (card.children && card.children.length > 0) {
        card.children.forEach(childId => {
          tree.push(...this.getCardTree(childId, allCards));
        });
      }
      return tree;
    },

    async performExport(ctx) {
      const format = this.exportPanel.querySelector('input[name="format"]:checked').value;
      const cards = this.getCardsToExport();

      if (cards.length === 0) {
        ctx.utils.showToast('No cards to export', 'error');
        return;
      }

      const options = {
        includeMetadata: this.exportPanel.querySelector('.include-metadata').checked,
        includeHierarchy: this.exportPanel.querySelector('.include-hierarchy').checked,
        includeToc: this.exportPanel.querySelector('.include-toc').checked,
        includeBacklinks: this.exportPanel.querySelector('.include-backlinks').checked
      };

      let content, filename, mimeType;

      switch (format) {
        case 'markdown':
          content = this.exportAsMarkdown(cards, options);
          filename = 'cardspoke-export.md';
          mimeType = 'text/markdown';
          break;

        case 'html':
          content = this.exportAsHTML(cards, options);
          filename = 'cardspoke-export.html';
          mimeType = 'text/html';
          break;

        case 'txt':
          content = this.exportAsText(cards, options);
          filename = 'cardspoke-export.txt';
          mimeType = 'text/plain';
          break;

        case 'csv':
          content = this.exportAsCSV(cards, options);
          filename = 'cardspoke-export.csv';
          mimeType = 'text/csv';
          break;

        case 'json':
          content = JSON.stringify(cards, null, 2);
          filename = 'cardspoke-export.json';
          mimeType = 'application/json';
          break;

        case 'pdf':
          this.exportAsPDF(cards, options, ctx);
          return;
      }

      this.downloadFile(content, filename, mimeType);
      ctx.utils.showToast(`Exported ${cards.length} card(s) as ${format.toUpperCase()}`, 'success');
      this.hideExportPanel();
    },

    exportAsMarkdown(cards, options) {
      let md = '';

      if (options.includeToc && cards.length > 1) {
        md += '# Table of Contents\n\n';
        cards.forEach((card, i) => {
          md += `${i + 1}. [${card.title}](#${this.slugify(card.title)})\n`;
        });
        md += '\n---\n\n';
      }

      cards.forEach(card => {
        md += `# ${card.title}\n\n`;

        if (options.includeMetadata) {
          md += `**Created:** ${new Date(card.createdAt).toLocaleString()}  \n`;
          md += `**Updated:** ${new Date(card.updatedAt).toLocaleString()}  \n`;
          if (card.tags && card.tags.length > 0) {
            md += `**Tags:** ${card.tags.map(t => `#${t}`).join(', ')}  \n`;
          }
          md += '\n';
        }

        md += card.body + '\n\n';
        md += '---\n\n';
      });

      return md;
    },

    exportAsHTML(cards, options) {
      let html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>CardSpoke Export</title>
  <style>
    body { font-family: sans-serif; max-width: 800px; margin: 40px auto; padding: 0 20px; }
    .card { margin-bottom: 40px; border-bottom: 2px solid #eee; padding-bottom: 20px; }
    .card-title { font-size: 1.8em; margin-bottom: 10px; }
    .card-meta { color: #666; font-size: 0.9em; margin-bottom: 15px; }
    .card-body { line-height: 1.6; }
    .tag { background: #e3f2fd; padding: 2px 8px; border-radius: 12px; font-size: 0.85em; }
  </style>
</head>
<body>
  <h1>CardSpoke Export</h1>
  <p>Exported on ${new Date().toLocaleString()}</p>
`;

      cards.forEach(card => {
        html += `  <div class="card">
    <div class="card-title">${this.escapeHtml(card.title)}</div>
`;

        if (options.includeMetadata) {
          html += `    <div class="card-meta">
      Created: ${new Date(card.createdAt).toLocaleString()} | 
      Updated: ${new Date(card.updatedAt).toLocaleString()}`;

          if (card.tags && card.tags.length > 0) {
            html += ` | Tags: ${card.tags.map(t => `<span class="tag">#${t}</span>`).join(' ')}`;
          }

          html += `
    </div>
`;
        }

        html += `    <div class="card-body">${this.escapeHtml(card.body).replace(/\n/g, '<br>')}</div>
  </div>
`;
      });

      html += `</body>
</html>`;
      return html;
    },

    exportAsText(cards, options) {
      let text = 'CARDSPOKE EXPORT\n';
      text += '='.repeat(80) + '\n\n';

      cards.forEach((card, i) => {
        text += `[${i + 1}] ${card.title}\n`;
        text += '-'.repeat(80) + '\n';

        if (options.includeMetadata) {
          text += `Created: ${new Date(card.createdAt).toLocaleString()}\n`;
          text += `Updated: ${new Date(card.updatedAt).toLocaleString()}\n`;
          if (card.tags && card.tags.length > 0) {
            text += `Tags: ${card.tags.join(', ')}\n`;
          }
          text += '\n';
        }

        text += card.body + '\n\n';
        text += '='.repeat(80) + '\n\n';
      });

      return text;
    },

    exportAsCSV(cards, options) {
      let csv = 'Title,Body,Created,Updated,Tags\n';

      cards.forEach(card => {
        const row = [
          this.escapeCSV(card.title),
          this.escapeCSV(card.body),
          new Date(card.createdAt).toISOString(),
          new Date(card.updatedAt).toISOString(),
          card.tags ? card.tags.join('; ') : ''
        ];
        csv += row.join(',') + '\n';
      });

      return csv;
    },

    exportAsPDF(cards, options, ctx) {
      // Generate HTML and trigger print dialog
      const html = this.exportAsHTML(cards, options);
      const printWindow = window.open('', '_blank');
      printWindow.document.write(html);
      printWindow.document.close();

      setTimeout(() => {
        printWindow.print();
      }, 500);

      ctx.utils.showToast('Opening print dialog for PDF export', 'info');
      this.hideExportPanel();
    },

    downloadFile(content, filename, mimeType) {
      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
    },

    slugify(text) {
      return text.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
    },

    escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    },

    escapeCSV(text) {
      if (text.includes(',') || text.includes('"') || text.includes('\n')) {
        return '"' + text.replace(/"/g, '""') + '"';
      }
      return text;
    },

    onDisable(ctx) {
      if (this.exportPanel && this.exportPanel.parentNode) {
        this.exportPanel.parentNode.removeChild(this.exportPanel);
      }
    }
  });
})();

