.export-btn {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-weight: bold;
}

.export-btn:hover {
  opacity: 0.9;
}

#advanced-export-panel {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  justify-content: center;
  align-items: center;
  z-index: 10001;
}

.export-modal {
  width: 90%;
  max-width: 600px;
  max-height: 90vh;
  background: var(--bg-primary);
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px;
  border-bottom: 2px solid var(--border);
}

.modal-header h2 {
  margin: 0;
  font-size: 1.5em;
}

.modal-close {
  background: none;
  border: none;
  font-size: 2em;
  cursor: pointer;
  color: var(--text-secondary);
  line-height: 1;
}

.modal-body {
  padding: 20px;
  overflow-y: auto;
  flex: 1;
}

.export-section {
  margin-bottom: 24px;
}

.export-section h3 {
  margin: 0 0 12px 0;
  font-size: 1.1em;
  color: var(--text-primary);
}

.format-options,
.scope-options,
.export-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.format-options label,
.scope-options label,
.export-options label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.format-options label:hover,
.scope-options label:hover,
.export-options label:hover {
  background: var(--bg-hover);
  border-color: var(--accent);
}

.tag-select {
  margin-top: 12px;
}

.tag-input {
  width: 100%;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg-alt);
  color: var(--text-primary);
}

.export-preview {
  padding: 16px;
  background: var(--bg-hover);
  border-radius: 8px;
  border-left: 4px solid var(--accent);
}

.preview-stats {
  display: flex;
  gap: 20px;
  font-size: 0.9em;
}

.preview-stats strong {
  color: var(--accent);
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  padding: 20px;
  border-top: 2px solid var(--border);
}

.modal-footer .btn {
  padding: 10px 20px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-weight: bold;
}

.btn-secondary {
  background: var(--bg-alt);
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-primary {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
}

.btn:hover {
  opacity: 0.9;
}
